```css
/* Volta Studio — Shared Styles */

@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,500;0,600;0,700;0,800;0,900;1,400;1,500;1,600;1,700&family=Inter:wght@300;400;500;600&display=swap');

:root {
  --bg: #F5F2ED;
  --bg-subtle: #EDE9E2;
  --text: #1A1A1A;
  --text-muted: #6B6560;
  --accent: #8B6F47;
  --terracotta: #C4704B;
  --sage: #8B9E82;
  --sand: #D4C5A9;
  --border: #E0DBD3;
  --font-serif: 'Playfair Display', Georgia, serif;
  --font-sans: 'Inter', system-ui, sans-serif;
  --max-width: 1200px;
  --reading-width: 680px;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg);
  color: var(--text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

/* --- Navigation --- */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  padding: 1.5rem 2.5rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--bg);
  mix-blend-mode: normal;
}

.nav-logo {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text);
  text-decoration: none;
  letter-spacing: -0.02em;
}

.nav-links {
  display: flex;
  gap: 2.5rem;
  list-style: none;
  align-items: center;
}

.nav-links a {
  font-family: var(--font-sans);
  font-size: 0.875rem;
  font-weight: 400;
  color: var(--text);
  text-decoration: none;
  letter-spacing: 0.02em;
  transition: opacity 0.2s ease;
}

.nav-links a:hover {
  opacity: 0.5;
}

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  z-index: 200;
  background: none;
  border: none;
  padding: 0.5rem;
}

.hamburger span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--text);
  transition: all 0.3s ease;
}

.hamburger.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.hamburger.active span:nth-child(2) {
  opacity: 0;
}

.hamburger.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* Mobile overlay */
.mobile-menu {
  position: fixed;
  inset: 0;
  background: var(--bg);
  z-index: 150;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 2rem;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
}

.mobile-menu.active {
  opacity: 1;
  pointer-events: all;
}

.mobile-menu a {
  font-family: var(--font-serif);
  font-size: 2.5rem;
  font-weight: 500;
  color: var(--text);
  text-decoration: none;
  transition: opacity 0.2s ease;
}

.mobile-menu a:hover {
  opacity: 0.5;
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
  }
  .hamburger {
    display: flex;
  }
  .nav {
    padding: 1.25rem 1.5rem;
  }
}

/* --- Marquee --- */
.marquee-container {
  overflow: hidden;
  padding: 3rem 0;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.marquee-row {
  display: flex;
  white-space: nowrap;
  will-change: transform;
}

.marquee-row .marquee-content {
  display: flex;
  align-items: center;
  animation: scroll-left 30s linear infinite;
  flex-shrink: 0;
}

.marquee-row.reverse .marquee-content {
  animation: scroll-right 30s linear infinite;
}

.marquee-item {
  font-family: var(--font-serif);
  font-size: 3rem;
  font-weight: 500;
  color: var(--text);
  padding: 0 1.5rem;
  white-space: nowrap;
  letter-spacing: -0.02em;
}

.marquee-dot {
  color: var(--text-muted);
  font-size: 1.5rem;
  padding: 0 0.5rem;
}

@keyframes scroll-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes scroll-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

/* --- Utility --- */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 2.5rem;
}

.reading-width {
  max-width: var(--reading-width);
}
```

