/* Volta Studio — Shared Styles */

@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,500;0,600;0,700;0,800;0,900;1,400;1,500;1,600;1,700&family=Inter:wght@300;400;500;600&display=swap');

:root {
  --bg: #F5F2ED;
  --bg-subtle: #EDE9E2;
  --text: #1A1A1A;
  --text-muted: #7A7570;
  --text-light: #9E9893;
  --accent: #8B6F47;
  --terracotta: #C4704B;
  --sage: #8B9E82;
  --sand: #D4C5A9;
  --border: #E0DBD3;
  --font-serif: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --max-width: 1200px;
  --reading-width: 640px;
}

*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg);
  color: var(--text);
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  display: block;
  max-width: 100%;
}

/* ========== NAVIGATION ========== */

.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  padding: 1.5rem 2.5rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--bg);
  transition: background 0.3s ease;
}

.nav-logo {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text);
  letter-spacing: -0.03em;
}

.nav-links {
  display: flex;
  gap: 2.5rem;
  list-style: none;
  align-items: center;
}

.nav-links a {
  font-family: var(--font-sans);
  font-size: 0.8125rem;
  font-weight: 400;
  color: var(--text);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  transition: opacity 0.2s ease;
}

.nav-links a:hover {
  opacity: 0.45;
}

.nav-links a.active {
  opacity: 0.45;
}

/* Hamburger Button */
.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  z-index: 200;
  background: none;
  border: none;
  padding: 0.5rem;
  width: 36px;
  height: 36px;
}

.hamburger span {
  display: block;
  width: 22px;
  height: 1.5px;
  background: var(--text);
  transition: all 0.35s cubic-bezier(0.4, 0, 0.2, 1);
  transform-origin: center;
}

.hamburger.active span:nth-child(1) {
  transform: rotate(45deg) translate(5.3px, 5.3px);
}

.hamburger.active span:nth-child(2) {
  opacity: 0;
  transform: scaleX(0);
}

.hamburger.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5.3px, -5.3px);
}

/* Mobile Menu Overlay */
.mobile-menu {
  position: fixed;
  inset: 0;
  background: var(--bg);
  z-index: 150;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 2.25rem;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

.mobile-menu.active {
  opacity: 1;
  pointer-events: all;
}

.mobile-menu a {
  font-family: var(--font-serif);
  font-size: 2.5rem;
  font-weight: 400;
  color: var(--text);
  letter-spacing: -0.02em;
  transition: opacity 0.2s ease;
}

.mobile-menu a:hover {
  opacity: 0.45;
}

/* ========== MARQUEE ========== */

.marquee-section {
  overflow: hidden;
  padding: 2.5rem 0;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.marquee-row {
  display: flex;
  width: max-content;
  padding: 0.5rem 0;
}

.marquee-track {
  display: flex;
  align-items: center;
  animation: marquee-left 40s linear infinite;
  flex-shrink: 0;
}

.marquee-row.reverse .marquee-track {
  animation: marquee-right 40s linear infinite;
}

.marquee-item {
  font-family: var(--font-serif);
  font-size: clamp(1.75rem, 4vw, 3.25rem);
  font-weight: 500;
  color: var(--text);
  padding: 0 1.25rem;
  white-space: nowrap;
  letter-spacing: -0.02em;
}

.marquee-separator {
  color: var(--text-light);
  font-size: 1.25rem;
  padding: 0 0.25rem;
  user-select: none;
}

@keyframes marquee-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes marquee-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

/* ========== LAYOUT UTILITIES ========== */

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 2.5rem;
}

.reading-width {
  max-width: var(--reading-width);
}

.section-divider {
  width: 60px;
  height: 1px;
  background: var(--border);
  margin: 4rem 0;
}

.full-divider {
  width: 100%;
  height: 1px;
  background: var(--border);
}

/* ========== TYPOGRAPHY ========== */

.heading-xl {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  font-weight: 600;
  line-height: 1.1;
  letter-spacing: -0.03em;
}

.heading-lg {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 500;
  line-height: 1.15;
  letter-spacing: -0.02em;
}

.heading-md {
  font-family: var(--font-serif);
  font-size: clamp(1.25rem, 2vw, 1.5rem);
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -0.01em;
}

.label-text {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.body-text {
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.75;
  color: var(--text);
}

.body-text-lg {
  font-family: var(--font-sans);
  font-size: clamp(1.0625rem, 1.5vw, 1.1875rem);
  line-height: 1.8;
  color: var(--text);
}

/* ========== RESPONSIVE ========== */

@media (max-width: 768px) {
  .nav {
    padding: 1.25rem 1.5rem;
  }

  .nav-links {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .container {
    padding: 0 1.5rem;
  }

  .marquee-item {
    font-size: 1.5rem;
    padding: 0 0.75rem;
  }

  .marquee-section {
    padding: 1.5rem 0;
  }

  .section-divider {
    margin: 2.5rem 0;
  }

  .mobile-menu a {
    font-size: 2rem;
  }
}

@media (max-width: 480px) {
  .container {
    padding: 0 1.25rem;
  }
}

